  KEY `idx_grouping_status` (`grouping_status`),
  KEY `idx_grouped_at` (`grouped_at`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabel kunjungan pasien dengan status grouping IDRG';

